#define _POSIX_C_SOURCE 200809L
#include "config_json.h"
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct parser { const char *s; size_t n, i, nodes; char *error; size_t error_n; } parser_t;
static void fail(parser_t *p,const char *m){ if(p->error&&p->error_n) snprintf(p->error,p->error_n,"%s at byte %zu",m,p->i); }
static void ws(parser_t*p){while(p->i<p->n&&(p->s[p->i]==' '||p->s[p->i]=='\t'||p->s[p->i]=='\r'||p->s[p->i]=='\n'))p->i++;}
static seedless_json_value_t *node(parser_t*p,seedless_json_type_t t){if(++p->nodes>4096){fail(p,"too many JSON values");return NULL;}seedless_json_value_t*v=calloc(1,sizeof *v);if(!v){fail(p,"out of memory");return NULL;}v->type=t;return v;}
static int utf8_append(char*out,size_t cap,size_t*used,uint32_t c){unsigned char b[4];size_t n;if(c<=0x7f){b[0]=c;n=1;}else if(c<=0x7ff){b[0]=0xc0|(c>>6);b[1]=0x80|(c&63);n=2;}else if(c<=0xffff){b[0]=0xe0|(c>>12);b[1]=0x80|((c>>6)&63);b[2]=0x80|(c&63);n=3;}else if(c<=0x10ffff){b[0]=0xf0|(c>>18);b[1]=0x80|((c>>12)&63);b[2]=0x80|((c>>6)&63);b[3]=0x80|(c&63);n=4;}else return 0;if(*used+n>=cap)return 0;memcpy(out+*used,b,n);*used+=n;return 1;}
static int hex4(parser_t*p,uint32_t*out){if(p->n-p->i<4)return 0;uint32_t v=0;for(int k=0;k<4;k++){char c=p->s[p->i++];unsigned d;if(c>='0'&&c<='9')d=c-'0';else if(c>='a'&&c<='f')d=c-'a'+10;else if(c>='A'&&c<='F')d=c-'A'+10;else return 0;v=(v<<4)|d;}*out=v;return 1;}
static int raw_utf8(parser_t*p,char*out,size_t cap,size_t*used){unsigned char c=p->s[p->i++];uint32_t cp;unsigned need;if(c<0x80){if(c==0)return 0;return utf8_append(out,cap,used,c);}if(c>=0xc2&&c<=0xdf){cp=c&31;need=1;}else if(c>=0xe0&&c<=0xef){cp=c&15;need=2;}else if(c>=0xf0&&c<=0xf4){cp=c&7;need=3;}else return 0;if(p->n-p->i<need)return 0;for(unsigned j=0;j<need;j++){unsigned char d=p->s[p->i++];if((d&0xc0)!=0x80)return 0;if(j==0&&((c==0xe0&&d<0xa0)||(c==0xed&&d>=0xa0)||(c==0xf0&&d<0x90)||(c==0xf4&&d>=0x90)))return 0;cp=(cp<<6)|(d&63);}return utf8_append(out,cap,used,cp);}
static char *string(parser_t*p){if(p->s[p->i++]!='"')return NULL;size_t cap=(p->n-p->i)*4+1,used=0;char*out=malloc(cap);if(!out){fail(p,"out of memory");return NULL;}while(p->i<p->n){unsigned char c=p->s[p->i];if(c=='"'){p->i++;out[used]=0;return out;}if(c<0x20){fail(p,"control byte in string");free(out);return NULL;}if(c=='\\'){p->i++;if(p->i>=p->n)break;char e=p->s[p->i++];uint32_t cp;switch(e){case '"':case '\\':case '/':cp=e;break;case 'b':cp='\b';break;case 'f':cp='\f';break;case 'n':cp='\n';break;case 'r':cp='\r';break;case 't':cp='\t';break;case 'u':if(!hex4(p,&cp))goto bad;if(cp>=0xd800&&cp<=0xdbff){if(p->n-p->i<6||p->s[p->i++]!='\\'||p->s[p->i++]!='u')goto bad;uint32_t lo;if(!hex4(p,&lo)||lo<0xdc00||lo>0xdfff)goto bad;cp=0x10000+((cp-0xd800)<<10)+(lo-0xdc00);}else if(cp>=0xdc00&&cp<=0xdfff)goto bad;break;default:goto bad;}if(cp==0||!utf8_append(out,cap,&used,cp))goto bad;}else if(!raw_utf8(p,out,cap,&used))goto bad;}bad:fail(p,"invalid or unterminated string");free(out);return NULL;}
static seedless_json_value_t *value(parser_t*,unsigned);
static void free_value(seedless_json_value_t*v){if(!v)return;if(v->type==SEEDLESS_JSON_STRING||v->type==SEEDLESS_JSON_NUMBER)free(v->as.string);seedless_json_member_t*m=v->members;while(m){seedless_json_member_t*n=m->next;free(m->key);free_value(m->value);free(m);m=n;}seedless_json_value_t*i=v->items;while(i){seedless_json_value_t*n=i->next;free_value(i);i=n;}free(v);}
static seedless_json_value_t *value(parser_t*p,unsigned depth){ws(p);if(depth>8){fail(p,"maximum nesting depth exceeded");return NULL;}if(p->i>=p->n){fail(p,"unexpected end of JSON");return NULL;}char c=p->s[p->i];if(c=='{'||c=='['){int obj=c=='{';p->i++;seedless_json_value_t*v=node(p,obj?SEEDLESS_JSON_OBJECT:SEEDLESS_JSON_ARRAY);if(!v)return NULL;ws(p);if(p->i<p->n&&p->s[p->i]==(obj?'}':']')){p->i++;return v;}seedless_json_member_t**mt=&v->members;seedless_json_value_t**it=&v->items;for(;;){ws(p);if(obj){if(p->i>=p->n||p->s[p->i]!='"'){fail(p,"object key must be a string");goto bad;}char*k=string(p);if(!k)goto bad;for(seedless_json_member_t*m=v->members;m;m=m->next)if(!strcmp(m->key,k)){free(k);fail(p,"duplicate object key");goto bad;}ws(p);if(p->i>=p->n||p->s[p->i++]!=':'){free(k);fail(p,"expected colon");goto bad;}seedless_json_value_t*x=value(p,depth+1);if(!x){free(k);goto bad;}seedless_json_member_t*m=calloc(1,sizeof*m);if(!m){free(k);free_value(x);fail(p,"out of memory");goto bad;}m->key=k;m->value=x;*mt=m;mt=&m->next;}else{seedless_json_value_t*x=value(p,depth+1);if(!x)goto bad;*it=x;it=&x->next;}ws(p);if(p->i>=p->n){fail(p,"unterminated container");goto bad;}char sep=p->s[p->i++];if(sep==(obj?'}':']'))return v;if(sep!=','){fail(p,"expected comma or container end");goto bad;}}bad:free_value(v);return NULL;}
 if(c=='"'){seedless_json_value_t*v=node(p,SEEDLESS_JSON_STRING);if(!v)return NULL;v->as.string=string(p);if(!v->as.string){free(v);return NULL;}return v;}
 if(c=='t'||c=='f'||c=='n'){const char*word=c=='t'?"true":c=='f'?"false":"null";size_t z=strlen(word);if(p->n-p->i<z||memcmp(p->s+p->i,word,z)){fail(p,"invalid literal");return NULL;}p->i+=z;seedless_json_value_t*v=node(p,c=='n'?SEEDLESS_JSON_NULL:SEEDLESS_JSON_BOOL);if(v)v->as.boolean=c=='t';return v;}
 size_t start=p->i;if(c=='-')p->i++;if(p->i>=p->n){fail(p,"invalid number");return NULL;}if(p->s[p->i]=='0')p->i++;else if(p->s[p->i]>='1'&&p->s[p->i]<='9'){while(p->i<p->n&&isdigit((unsigned char)p->s[p->i]))p->i++;}else{fail(p,"invalid number");return NULL;}int integer=1;if(p->i<p->n&&p->s[p->i]=='.'){integer=0;p->i++;if(p->i>=p->n||!isdigit((unsigned char)p->s[p->i]))goto numbad;while(p->i<p->n&&isdigit((unsigned char)p->s[p->i]))p->i++;}if(p->i<p->n&&(p->s[p->i]=='e'||p->s[p->i]=='E')){integer=0;p->i++;if(p->i<p->n&&(p->s[p->i]=='+'||p->s[p->i]=='-'))p->i++;if(p->i>=p->n||!isdigit((unsigned char)p->s[p->i]))goto numbad;while(p->i<p->n&&isdigit((unsigned char)p->s[p->i]))p->i++;}seedless_json_value_t*v=node(p,integer?SEEDLESS_JSON_INTEGER:SEEDLESS_JSON_NUMBER);if(!v)return NULL;if(integer){char tmp[32];size_t z=p->i-start;if(z>=sizeof tmp){fail(p,"integer overflow");free(v);return NULL;}memcpy(tmp,p->s+start,z);tmp[z]=0;char*end;long long q=strtoll(tmp,&end,10);if(*end){fail(p,"integer overflow");free(v);return NULL;}v->as.integer=q;}else{v->as.string=strndup(p->s+start,p->i-start);if(!v->as.string){free(v);return NULL;}}return v;numbad:fail(p,"invalid number");return NULL;}
int seedless_json_parse(const char*d,size_t n,seedless_json_doc_t*doc,char*e,size_t en){if(!d||!doc||n>65536)return 0;memset(doc,0,sizeof *doc);parser_t p={.s=d,.n=n,.error=e,.error_n=en};doc->root=value(&p,0);if(!doc->root)return 0;ws(&p);if(p.i!=n){fail(&p,"trailing JSON data");seedless_json_free(doc);return 0;}doc->nodes=p.nodes;return 1;}
void seedless_json_free(seedless_json_doc_t*d){if(d){free_value(d->root);memset(d,0,sizeof*d);}}
const seedless_json_value_t*seedless_json_get(const seedless_json_value_t*v,const char*k){if(!v||v->type!=SEEDLESS_JSON_OBJECT)return NULL;for(seedless_json_member_t*m=v->members;m;m=m->next)if(!strcmp(m->key,k))return m->value;return NULL;}
int seedless_json_write_string(const char*s,char*out,size_t cap,size_t*written){if(!s||!out||cap<3)return 0;size_t n=0;out[n++]='"';for(const unsigned char*p=(const unsigned char*)s;*p;p++){const char*esc=NULL;char tmp[7];switch(*p){case '"':esc="\\\"";break;case '\\':esc="\\\\";break;case '\b':esc="\\b";break;case '\f':esc="\\f";break;case '\n':esc="\\n";break;case '\r':esc="\\r";break;case '\t':esc="\\t";break;default:if(*p<0x20){snprintf(tmp,sizeof tmp,"\\u%04x",*p);esc=tmp;}}if(esc){size_t z=strlen(esc);if(n+z+2>cap)return 0;memcpy(out+n,esc,z);n+=z;}else{if(n+2>cap)return 0;out[n++]=*p;}}if(n+2>cap)return 0;out[n++]='"';out[n]=0;if(written)*written=n;return 1;}
